def matches(text):
    fm = re_search(r'^From: (.+)$', text, MULTILINE)
    if fm is None:
        return False
    addr = parseaddr(fm.group(1))[1].lower()
    if addr != 'billing@kestrelcloud.example':
        return False
    for marker in [r'^Invoice date: ', r'^Billing period: ', r'^Total due: \$']:
        if re_search(marker, text, MULTILINE) is None:
            return False
    return True


def parse(text):
    if not matches(text):
        raise ValueError('not a Kestrel Cloud invoice')
    vendor_m = re_search(r'^(.+)\nInvoice: INV-', text, MULTILINE)
    inv_m = re_search(r'^Invoice: INV-(.+)$', text, MULTILINE)
    subj_m = re_search(r'^Subject: .*INV-(\S+)\s*$', text, MULTILINE)
    date_m = re_search(r'^Invoice date: (.+)$', text, MULTILINE)
    period_m = re_search(r'^Billing period: (.+?) - (.+)$', text, MULTILINE)
    total_m = re_search(r'^Total due: \$([0-9,]+\.[0-9]{2})$', text, MULTILINE)
    if vendor_m is None or inv_m is None or subj_m is None or date_m is None or period_m is None or total_m is None:
        raise ValueError('expected line missing')
    inv_number = inv_m.group(1).strip()
    if subj_m.group(1).strip() != inv_number:
        raise ValueError('subject invoice number disagrees with body')
    items = re_findall(r'^(.+?) {2,}\$([0-9,]+\.[0-9]{2})$', text, MULTILINE)
    if not items:
        raise ValueError('no line items')
    total = Decimal(total_m.group(1).replace(',', ''))
    line_sum = sum((Decimal(a.replace(',', '')) for _, a in items), Decimal('0'))
    if line_sum != total:
        raise ValueError('line items do not add up to total')
    invoice_date = datetime.strptime(date_m.group(1).strip(), '%B %d, %Y').date().isoformat()
    start = datetime.strptime(period_m.group(1).strip(), '%B %d, %Y').date().isoformat()
    end = datetime.strptime(period_m.group(2).strip(), '%B %d, %Y').date().isoformat()
    if end < start:
        raise ValueError('billing period ends before it starts')
    quotes = [inv_m.group(0), date_m.group(0), period_m.group(0), total_m.group(0)]
    return {'contacts': [], 'invoice_facts': [{'amount': float(total), 'billing_period': start + '/' + end, 'invoice_date': invoice_date, 'invoice_number': inv_number, 'quotes': quotes, 'seats_billed': None}], 'terms': [], 'vendor_name': vendor_m.group(1).strip()}
